import{_ as o,r as a,o as p,c as i,e as t,a as c,s as d}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Image Resizer - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Introduction","slug":"introduction","link":"#introduction","children":[{"level":3,"title":"Resize Parameters","slug":"resize-parameters","link":"#resize-parameters","children":[]},{"level":3,"title":"Available Modes","slug":"available-modes","link":"#available-modes","children":[]}]}],"relativePath":"2.x/services/resizer.md","filePath":"2.x/services/resizer.md"}'),r={name:"2.x/services/resizer.md"};function l(h,e,u,g,m,k){const s=a("pre-heading"),n=a("post-heading");return p(),i("div",null,[t(s),e[0]||(e[0]=c("h1",null,"Image Resizer",-1)),t(n),e[1]||(e[1]=d(`<h2 id="introduction"><a href="#introduction" class="header-anchor">#</a> Introduction</h2><p>October CMS ships with an image resizer that lets you change the shape and size of supported images. To resize an image, use the <code>open</code> method on the <code>Resizer</code> facade to target a file path.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name static-context">Resizer</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/image.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>You may also pass an uploaded file from the <a href="./../services/request-input.html">page request input</a>.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span> <span class="token operator">=</span> <span class="token class-name static-context">Resizer</span><span class="token operator">::</span><span class="token function">open</span><span class="token punctuation">(</span><span class="token class-name static-context">Input</span><span class="token operator">::</span><span class="token function">file</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;field_name&#39;</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>To resize the image, call the <code>resize</code> method on the object to perform the resize. The first argument is the image width, the second argument is the image height and the third argument is an array of <a href="#oc-resize-parameters">resize parameters</a> options.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token number">600</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;mode&#39;</span> <span class="token operator">=&gt;</span> <span class="token string single-quoted-string">&#39;crop&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>The width and height arguments are also optional, for example, to use the existing width and only adjust the height, pass the second argument as <code>null</code>. This value is then calculated using original image ratio (automatic proportional scaling) based on the <code>mode</code> option.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">resize</span><span class="token punctuation">(</span><span class="token number">800</span><span class="token punctuation">,</span> <span class="token constant">null</span><span class="token punctuation">,</span> <span class="token punctuation">[</span><span class="token operator">...</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>Finally, use the <code>save</code> method to save the resized image to a new location.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token variable">$image</span><span class="token operator">-&gt;</span><span class="token function">save</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;path/to/new/file.jpg&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><blockquote><p><strong>Note</strong>: There is also a <code>|resize</code> <a href="./../markup/filter-resize.html">markup filter</a> that can be used for resizing images in your themes.</p></blockquote><p><a id="oc-resize-parameters"></a></p><h3 id="resize-parameters"><a href="#resize-parameters" class="header-anchor">#</a> Resize Parameters</h3><p>The following elements are supported in the options array are supported:</p><div class="table"><table tabindex="0"><thead><tr><th>Key</th><th>Description</th><th>Default</th><th>Options</th></tr></thead><tbody><tr><td><code>mode</code></td><td>How the image should be fitted to dimensions</td><td><code>auto</code></td><td><code>exact</code>, <code>portrait</code>, <code>landscape</code>, <code>auto</code>, <code>fit</code>, or <code>crop</code></td></tr><tr><td><code>offset</code></td><td>Offset the crop of the resized image</td><td><code>[0,0]</code></td><td>[left, top]</td></tr><tr><td><code>quality</code></td><td>Quality of the resized image</td><td><code>90</code></td><td><code>0-100</code></td></tr><tr><td><code>sharpen</code></td><td>Amount to sharpen the image</td><td><code>0</code></td><td><code>0-100</code></td></tr></tbody></table></div><h3 id="available-modes"><a href="#available-modes" class="header-anchor">#</a> Available Modes</h3><p>The <code>mode</code> option allows you to specify how the image should be resized. The available modes are as follows:</p><div class="table"><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><code>auto</code></td><td>Automatically choose between <code>portrait</code> and <code>landscape</code> based on the image&#39;s orientation</td></tr><tr><td><code>exact</code></td><td>Resize to the exact dimensions given, without preserving aspect ratio</td></tr><tr><td><code>portrait</code></td><td>Resize to the given height and adapt the width to preserve aspect ratio</td></tr><tr><td><code>landscape</code></td><td>Resize to the given width and adapt the height to preserve aspect ratio</td></tr><tr><td><code>crop</code></td><td>Crop to the given dimensions after fitting as much of the image as possible inside those</td></tr><tr><td><code>fit</code></td><td>Fit the image inside the given maximal dimensions, keeping the aspect ratio</td></tr></tbody></table></div>`,19))])}const b=o(r,[["render",l]]);export{v as __pageData,b as default};
